Here's a complete, self-contained checkout screen for a Telegram Mini App. It renders the cart summary, a validated delivery address form, and a Pay button, with Telegram `BackButton`/haptics wired in when running inside Telegram (falls back gracefully outside it).

**CheckoutScreen.tsx**
```tsx
import React, { useCallback, useEffect, useMemo, useState } from 'react';
import './CheckoutScreen.css';

export interface CartItem {
  id: string;
  name: string;
  imageUrl?: string;
  price: number;
  quantity: number;
}

export interface DeliveryAddress {
  fullName: string;
  phone: string;
  city: string;
  street: string;
  apartment: string;
  postalCode: string;
  comment: string;
}

export interface CheckoutScreenProps {
  items: CartItem[];
  currency?: string;
  deliveryFee?: number;
  initialAddress?: Partial<DeliveryAddress>;
  onBack: () => void;
  onPay: (address: DeliveryAddress) => Promise<void> | void;
}

type FormErrors = Partial<Record<keyof DeliveryAddress, string>>;

const EMPTY_ADDRESS: DeliveryAddress = {
  fullName: '',
  phone: '',
  city: '',
  street: '',
  apartment: '',
  postalCode: '',
  comment: '',
};

function formatPrice(amount: number, currency: string): string {
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency,
    minimumFractionDigits: 2,
  }).format(amount);
}

function getTelegramWebApp() {
  return (window as any)?.Telegram?.WebApp ?? null;
}

function validate(address: DeliveryAddress): FormErrors {
  const errors: FormErrors = {};
  if (!address.fullName.trim()) errors.fullName = 'Enter your full name';
  if (!address.phone.trim()) {
    errors.phone = 'Enter a phone number';
  } else if (!/^\+?[0-9\s-]{7,15}$/.test(address.phone.trim())) {
    errors.phone = 'Enter a valid phone number';
  }
  if (!address.city.trim()) errors.city = 'Enter a city';
  if (!address.street.trim()) errors.street = 'Enter a street address';
  if (!address.postalCode.trim()) {
    errors.postalCode = 'Enter a postal code';
  } else if (!/^[A-Za-z0-9\s-]{3,10}$/.test(address.postalCode.trim())) {
    errors.postalCode = 'Enter a valid postal code';
  }
  return errors;
}

export default function CheckoutScreen({
  items,
  currency = 'USD',
  deliveryFee = 0,
  initialAddress,
  onBack,
  onPay,
}: CheckoutScreenProps) {
  const [address, setAddress] = useState<DeliveryAddress>({
    ...EMPTY_ADDRESS,
    ...initialAddress,
  });
  const [touched, setTouched] = useState<Partial<Record<keyof DeliveryAddress, boolean>>>({});
  const [submitting, setSubmitting] = useState(false);
  const [payError, setPayError] = useState<string | null>(null);

  const errors = useMemo(() => validate(address), [address]);

  const subtotal = useMemo(
    () => items.reduce((sum, item) => sum + item.price * item.quantity, 0),
    [items]
  );
  const total = subtotal + deliveryFee;
  const hasItems = items.length > 0;

  useEffect(() => {
    const tg = getTelegramWebApp();
    if (!tg) return;
    tg.BackButton.show();
    tg.BackButton.onClick(onBack);
    return () => {
      tg.BackButton.offClick(onBack);
      tg.BackButton.hide();
    };
  }, [onBack]);

  const handleChange = useCallback(
    (field: keyof DeliveryAddress) =>
      (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
        const { value } = e.target;
        setAddress((prev) => ({ ...prev, [field]: value }));
      },
    []
  );

  const handleBlur = useCallback(
    (field: keyof DeliveryAddress) => () => {
      setTouched((prev) => ({ ...prev, [field]: true }));
    },
    []
  );

  const handlePay = useCallback(async () => {
    const validationErrors = validate(address);
    if (Object.keys(validationErrors).length > 0) {
      setTouched({
        fullName: true,
        phone: true,
        city: true,
        street: true,
        apartment: true,
        postalCode: true,
        comment: true,
      });
      return;
    }
    const tg = getTelegramWebApp();
    tg?.HapticFeedback?.impactOccurred('medium');
    setPayError(null);
    setSubmitting(true);
    try {
      await onPay(address);
    } catch (err) {
      setPayError(err instanceof Error ? err.message : 'Payment failed. Please try again.');
      tg?.HapticFeedback?.notificationOccurred('error');
    } finally {
      setSubmitting(false);
    }
  }, [address, onPay]);

  return (
    <div className="checkout">
      <header className="checkout__header">
        <button type="button" className="checkout__back" onClick={onBack} aria-label="Back to cart">
          <svg width="20" height="20" viewBox="0 0 24 24" fill="none" aria-hidden="true">
            <path
              d="M15 18l-6-6 6-6"
              stroke="currentColor"
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </svg>
        </button>
        <h1 className="checkout__title">Checkout</h1>
      </header>

      <div className="checkout__content">
        <section className="checkout__section" aria-labelledby="cart-heading">
          <h2 id="cart-heading" className="checkout__section-title">
            Your order
          </h2>
          {hasItems ? (
            <ul className="cart-list">
              {items.map((item) => (
                <li key={item.id} className="cart-list__item">
                  <div className="cart-list__thumb">
                    {item.imageUrl ? (
                      <img src={item.imageUrl} alt="" />
                    ) : (
                      <span className="cart-list__thumb-fallback">{item.name.charAt(0)}</span>
                    )}
                  </div>
                  <div className="cart-list__info">
                    <span className="cart-list__name">{item.name}</span>
                    <span className="cart-list__qty">Qty {item.quantity}</span>
                  </div>
                  <span className="cart-list__price">
                    {formatPrice(item.price * item.quantity, currency)}
                  </span>
                </li>
              ))}
            </ul>
          ) : (
            <p className="checkout__empty">Your cart is empty.</p>
          )}

          <dl className="order-summary">
            <div className="order-summary__row">
              <dt>Subtotal</dt>
              <dd>{formatPrice(subtotal, currency)}</dd>
            </div>
            <div className="order-summary__row">
              <dt>Delivery</dt>
              <dd>{deliveryFee > 0 ? formatPrice(deliveryFee, currency) : 'Free'}</dd>
            </div>
            <div className="order-summary__row order-summary__row--total">
              <dt>Total</dt>
              <dd>{formatPrice(total, currency)}</dd>
            </div>
          </dl>
        </section>

        <section className="checkout__section" aria-labelledby="address-heading">
          <h2 id="address-heading" className="checkout__section-title">
            Delivery address
          </h2>

          <form className="address-form" noValidate>
            <div className="field">
              <label htmlFor="fullName">Full name</label>
              <input
                id="fullName"
                type="text"
                autoComplete="name"
                value={address.fullName}
                onChange={handleChange('fullName')}
                onBlur={handleBlur('fullName')}
                className={
                  touched.fullName && errors.fullName ? 'field__input field__input--error' : 'field__input'
                }
              />
              {touched.fullName && errors.fullName && (
                <span className="field__error">{errors.fullName}</span>
              )}
            </div>

            <div className="field">
              <label htmlFor="phone">Phone number</label>
              <input
                id="phone"
                type="tel"
                autoComplete="tel"
                value={address.phone}
                onChange={handleChange('phone')}
                onBlur={handleBlur('phone')}
                className={touched.phone && errors.phone ? 'field__input field__input--error' : 'field__input'}
              />
              {touched.phone && errors.phone && <span className="field__error">{errors.phone}</span>}
            </div>

            <div className="field-row">
              <div className="field">
                <label htmlFor="city">City</label>
                <input
                  id="city"
                  type="text"
                  autoComplete="address-level2"
                  value={address.city}
                  onChange={handleChange('city')}
                  onBlur={handleBlur('city')}
                  className={touched.city && errors.city ? 'field__input field__input--error' : 'field__input'}
                />
                {touched.city && errors.city && <span className="field__error">{errors.city}</span>}
              </div>

              <div className="field">
                <label htmlFor="postalCode">Postal code</label>
                <input
                  id="postalCode"
                  type="text"
                  autoComplete="postal-code"
                  value={address.postalCode}
                  onChange={handleChange('postalCode')}
                  onBlur={handleBlur('postalCode')}
                  className={
                    touched.postalCode && errors.postalCode
                      ? 'field__input field__input--error'
                      : 'field__input'
                  }
                />
                {touched.postalCode && errors.postalCode && (
                  <span className="field__error">{errors.postalCode}</span>
                )}
              </div>
            </div>

            <div className="field">
              <label htmlFor="street">Street address</label>
              <input
                id="street"
                type="text"
                autoComplete="address-line1"
                value={address.street}
                onChange={handleChange('street')}
                onBlur={handleBlur('street')}
                className={touched.street && errors.street ? 'field__input field__input--error' : 'field__input'}
              />
              {touched.street && errors.street && <span className="field__error">{errors.street}</span>}
            </div>

            <div className="field">
              <label htmlFor="apartment">Apartment, suite, etc. (optional)</label>
              <input
                id="apartment"
                type="text"
                autoComplete="address-line2"
                value={address.apartment}
                onChange={handleChange('apartment')}
                className="field__input"
              />
            </div>

            <div className="field">
              <label htmlFor="comment">Delivery notes (optional)</label>
              <textarea
                id="comment"
                rows={2}
                value={address.comment}
                onChange={handleChange('comment')}
                className="field__input field__textarea"
              />
            </div>
          </form>
        </section>
      </div>

      <footer className="checkout__footer">
        {payError && <p className="checkout__pay-error">{payError}</p>}
        <button type="button" className="pay-button" onClick={handlePay} disabled={!hasItems || submitting}>
          {submitting ? (
            <span className="pay-button__spinner" aria-hidden="true" />
          ) : (
            <span>Pay {formatPrice(total, currency)}</span>
          )}
        </button>
      </footer>
    </div>
  );
}
```

